    invoke_to_comStatusIn(0, failure);  // First retry fails
    invoke_to_dataReturnIn(0, buffer, nullContext);  // Buffer returned after retry failure
    invoke_to_comStatusIn(0, failure);  // Second retry fails (all retries exhausted)

